import{_ as n,o as s,c as p,a5 as t}from"./chunks/framework.BEZBAInb.js";const q=JSON.parse('{"title":"分支","description":"","frontmatter":{"title":"分支","order":4},"headers":[],"relativePath":"zh/2.4/tutorial/script/branch.md","filePath":"zh/2.4/tutorial/script/branch.md","lastUpdated":1788455378000}'),e={name:"zh/2.4/tutorial/script/branch.md"};function o(c,a,l,i,h,u){return s(),p("div",null,[...a[0]||(a[0]=[t(`<h1 id="分支" tabindex="-1">分支 <a class="header-anchor" href="#分支" aria-label="Permalink to &quot;分支&quot;">​</a></h1><h2 id="功能描述" tabindex="-1">功能描述 <a class="header-anchor" href="#功能描述" aria-label="Permalink to &quot;功能描述&quot;">​</a></h2><p>分支是用于组织脚本内容的一种方式，通过分支可以方便地管理和调用脚本中的不同部分，用于实现复杂的跳转逻辑，该功能一般搭配选项使用。</p><p>可以将标签理解为脚本中的“书签”，通过标签可以快速定位到脚本中的特定位置，由标签和缩进包裹的内容即为标签的内容，这部分脚本内容在执行当前标签对话的时候，会被添加到对话列表中，否则只会保存到标签对话中，不会触发播放。</p><p>分支不可以<strong>嵌套使用</strong>，分支的缩进层级必须和对话的缩进层级一致，否则会导致无法正常解析，以下是错误的示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 错误的示例：嵌套使用</span></span>
<span class="line"><span>branch drink_water</span></span>
<span class="line"><span>    &quot;kona&quot; &quot;我想喝水&quot;</span></span>
<span class="line"><span>        branch eat_cake</span></span>
<span class="line"><span>            &quot;kona&quot; &quot;我想吃蛋糕&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 错误的示例：缩进层级不一致，导致分支内无内容</span></span>
<span class="line"><span>branch drink_tea</span></span>
<span class="line"><span>&quot;kona&quot; &quot;我想喝茶&quot;</span></span></code></pre></div><p>一般正确的分支结合选项使用，例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>choice &quot;送花（好感+10）&quot; -&gt; gift_flower</span></span>
<span class="line"><span></span></span>
<span class="line"><span>choice &quot;送书（好感+5）&quot; -&gt; gift_book</span></span>
<span class="line"><span></span></span>
<span class="line"><span>choice &quot;什么都不送（好感-5）&quot; -&gt; gift_none</span></span>
<span class="line"><span></span></span>
<span class="line"><span>choice &quot;离开&quot; -&gt; exit_choice</span></span>
<span class="line"><span></span></span>
<span class="line"><span>branch gift_flower</span></span>
<span class="line"><span>    actor change Kona 害羞</span></span>
<span class="line"><span>    &quot;Kona&quot; &quot;哇，花很漂亮！谢谢你！&quot;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    choice &quot;继续聊天&quot; -&gt; chat_more</span></span>
<span class="line"><span>    choice &quot;告别离开&quot; -&gt; exit_choice</span></span>
<span class="line"><span></span></span>
<span class="line"><span>branch gift_book</span></span>
<span class="line"><span>    actor change Kona 惊讶</span></span>
<span class="line"><span>    &quot;Kona&quot; &quot;这本书看起来很有趣，谢谢！&quot;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    choice &quot;继续聊天&quot; -&gt; chat_more</span></span>
<span class="line"><span>    choice &quot;告别离开&quot; -&gt; exit_choice</span></span>
<span class="line"><span></span></span>
<span class="line"><span>branch gift_none</span></span>
<span class="line"><span>    actor change Kona 正常</span></span>
<span class="line"><span>    &quot;Kona&quot; &quot;没关系，下次再送吧。&quot;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    choice &quot;继续聊天&quot; -&gt; chat_more</span></span>
<span class="line"><span>    choice &quot;告别离开&quot; -&gt; exit_choice</span></span>
<span class="line"><span></span></span>
<span class="line"><span>branch chat_more</span></span>
<span class="line"><span>    actor change Kona 正常</span></span>
<span class="line"><span>    &quot;Kona&quot; &quot;你想聊什么话题呢？&quot;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    choice &quot;聊聊旅行&quot; -&gt; topic_travel</span></span>
<span class="line"><span>    choice &quot;聊聊美食&quot; -&gt; topic_food</span></span>
<span class="line"><span>    choice &quot;告别离开&quot; -&gt; exit_choice</span></span>
<span class="line"><span></span></span>
<span class="line"><span>branch topic_travel</span></span>
<span class="line"><span>    actor change Kona 惊讶</span></span>
<span class="line"><span>    &quot;Kona&quot; &quot;我也很喜欢旅行！下次一起去吧！&quot;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    choice &quot;送花&quot; -&gt; gift_flower</span></span>
<span class="line"><span>    choice &quot;告别离开&quot; -&gt; exit_choice</span></span>
<span class="line"><span></span></span>
<span class="line"><span>branch topic_food</span></span>
<span class="line"><span>    actor change Kona 害羞</span></span>
<span class="line"><span>    &quot;Kona&quot; &quot;美食话题我最喜欢了！&quot;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    choice &quot;送书&quot; -&gt; gift_book</span></span>
<span class="line"><span>    choice &quot;告别离开&quot; -&gt; exit_choice</span></span>
<span class="line"><span></span></span>
<span class="line"><span>branch exit_choice</span></span>
<span class="line"><span>    actor change Kona 正常</span></span>
<span class="line"><span>    &quot;Kona&quot; &quot;再见，期待下次见面！&quot;</span></span>
<span class="line"><span>    actor exit Kona</span></span>
<span class="line"><span>    background bg_end fade</span></span>
<span class="line"><span>    end</span></span></code></pre></div><h2 id="语法结构" tabindex="-1">语法结构 <a class="header-anchor" href="#语法结构" aria-label="Permalink to &quot;语法结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>branch [标签ID]</span></span>
<span class="line"><span>    [脚本内容]</span></span></code></pre></div><h2 id="参数详解" tabindex="-1">参数详解 <a class="header-anchor" href="#参数详解" aria-label="Permalink to &quot;参数详解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>必需</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td>标签ID</td><td>是</td><td><code>drink_water</code></td><td>标签标识符</td></tr></tbody></table><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>branch drink_water</span></span>
<span class="line"><span>    &quot;kona&quot; &quot;我想喝水&quot;</span></span>
<span class="line"><span>branch drink_tea</span></span>
<span class="line"><span>    &quot;kona&quot; &quot;我想喝茶&quot;</span></span></code></pre></div>`,14)])])}const d=n(e,[["render",o]]);export{q as __pageData,d as default};
